SELECT e.name,r.rolname,x.privilege,has_table_privilege(r.oid,c.oid,x.privilege)=(r.rolname='authenticated' AND x.privilege=ANY(e.allowed)) AS exact_access FROM (VALUES ('training_sessions',ARRAY['SELECT']::text[]),('training_session_records',ARRAY['SELECT','INSERT','UPDATE']::text[]),('training_block_results',ARRAY['SELECT','INSERT','UPDATE']::text[]),('training_exercise_results',ARRAY['SELECT','INSERT','UPDATE']::text[]),('training_set_results',ARRAY['SELECT','INSERT','UPDATE']::text[]),('performance_result_corrections',ARRAY['SELECT']::text[]),('coach_athlete_relationships',ARRAY['SELECT']::text[]),('profiles',ARRAY['SELECT','INSERT','UPDATE']::text[])) e(name,allowed) JOIN pg_class c ON c.relnamespace='public'::regnamespace AND c.relname=e.name CROSS JOIN pg_roles r CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN']) x(privilege) WHERE r.rolname IN ('anon','authenticated') ORDER BY e.name,r.rolname,x.privilege;
